import re
from dataclasses import dataclass

_NUMBER = r"(\d+(?:[.,]\d+)?)"
_PATTERNS = {
    "protein": re.compile(r"белки\s+" + _NUMBER),
    "fat": re.compile(r"жиры\s+" + _NUMBER),
    "carbs": re.compile(r"углеводы\s+" + _NUMBER),
    "kcal": re.compile(_NUMBER + r"\s*ккал"),
}
_LABELS = {"protein": "белки", "fat": "жиры", "carbs": "углеводы", "kcal": "ккал"}


@dataclass(frozen=True)
class Kbju:
    protein: float
    fat: float
    carbs: float
    kcal: float


def parse_kbju(value: str) -> Kbju:
    block = value.split("<br>", 1)[0]
    numbers = {}
    for field, pattern in _PATTERNS.items():
        match = pattern.search(block)
        if match is None:
            raise ValueError(f"в строке КБЖУ нет значения «{_LABELS[field]}»: {block!r}")
        numbers[field] = float(match.group(1).replace(",", "."))
    if numbers["kcal"] <= 0:
        raise ValueError(f"ккал в строке КБЖУ должны быть больше нуля: {block!r}")
    return Kbju(**numbers)
import html
from itertools import combinations

from core.kbju import parse_kbju
from core.scoring import score

KBJU_PROPERTY = "Пищевая и энергетическая ценность в 100 г"
MIN_WINNER_GAP = 0.03


def describe_product(item: dict) -> dict:
    """Товар ВкусВилла (из поиска или product_details) → id, название, КБЖУ, скор."""
    value = next((p["value"] for p in item.get("properties", []) if p["name"] == KBJU_PROPERTY), None)
    if value is None:
        raise ValueError(f"у товара {item['id']} нет КБЖУ: выбери другой товар")
    kbju = parse_kbju(value)
    return {
        "id": item["id"],
        "xml_id": item["xml_id"],
        "name": html.unescape(item["name"]),
        "kbju": {"protein": kbju.protein, "fat": kbju.fat, "carbs": kbju.carbs, "kcal": kbju.kcal},
        "score": score(kbju),
    }


def _single_winner(products: list[dict]) -> dict | None:
    first, second = sorted(products, key=lambda p: p["score"], reverse=True)[:2]
    # Скоры округлены до 3 знаков; без round 0.141 - 0.111 во float меньше 0.03.
    if round(first["score"] - second["score"], 3) < MIN_WINNER_GAP:
        return None
    return first


def build_round(query: str, items: list[dict]) -> dict:
    if not query.strip():
        raise ValueError("поисковый запрос пуст: укажи категорию, например «творог»")
    candidates = {}
    for item in items:
        if item["id"] in candidates:
            continue
        try:
            candidates[item["id"]] = describe_product(item)
        except ValueError:
            continue
    for triple in combinations(candidates.values(), 3):
        winner = _single_winner(list(triple))
        if winner is None:
            continue
        losers = [p for p in triple if p is not winner]
        # Позиция победителя зависит от id, а не от скора и порядка поиска.
        position = sum(p["id"] for p in triple) % 3
        products = losers[:position] + [winner] + losers[position:]
        return {"query": query, "products": products, "winner_id": winner["id"]}
    raise ValueError(
        f"по запросу «{query}» не нашлось трёх товаров с КБЖУ, где лучший опережает "
        f"второго на {MIN_WINNER_GAP} и больше: попробуй другой запрос или увеличь limit"
    )


def judge_round(products: list[dict], choice_id: int) -> dict:
    if len(products) != 3:
        raise ValueError(f"в раунде должно быть ровно 3 товара, передано {len(products)}")
    ids = [p["id"] for p in products]
    if len(set(ids)) != 3:
        raise ValueError(f"товары в раунде повторяются: {ids}, нужны 3 разных id")
    if choice_id not in ids:
        raise ValueError(f"выбранный товар {choice_id} не из раунда: выбери один из {ids}")
    described = [describe_product(p) for p in products]
    best = max(p["score"] for p in described)
    leaders = [p for p in described if p["score"] == best]
    if len(leaders) > 1:
        raise ValueError(f"у товаров {[p['id'] for p in leaders]} одинаковый лучший скор: победителя нет")
    winner_id = leaders[0]["id"]
    return {
        "correct": choice_id == winner_id,
        "winner_id": winner_id,
        "scores": {p["id"]: p["score"] for p in described},
    }
from core.kbju import Kbju


def score(kbju: Kbju) -> float:
    if kbju.kcal <= 0:
        raise ValueError("ккал должны быть больше нуля")
    return round(kbju.protein * 4 / kbju.kcal, 3)


def coins_for_answer(correct: bool, streak: int) -> int:
    """streak — длина серии верных ответов подряд, включая текущий."""
    if streak < 0:
        raise ValueError("длина серии не может быть отрицательной")
    if correct and streak < 1:
        raise ValueError("при верном ответе серия должна быть не меньше 1")
    if not correct:
        return 0
    if streak >= 3:
        return 15
    return 10


# Нижняя граница процента -> ранг, от старшего к младшему.
_RANKS = [
    (100, "true adam"),
    (80, "chad"),
    (70, "chadlite"),
    (60, "HTN"),
    (50, "MTN"),
    (40, "LTN"),
    (20, "sub5"),
    (0, "sub3"),
]


def rank(correct_count: int) -> str:
    if not 0 <= correct_count <= 10:
        raise ValueError("число верных ответов должно быть от 0 до 10")
    percent = correct_count / 10 * 100
    for threshold, name in _RANKS:
        if percent >= threshold:
            return name
import json
import urllib.request
from typing import Callable

MCP_URL = "https://mcp.vkusvill.ru/mcp"
# QRATOR перед mcp.vkusvill.ru отвечает 403 на User-Agent «Python-urllib/…».
_USER_AGENT = "looksmax-grocery/1.0"

Transport = Callable[[dict], dict]


def http_transport(payload: dict, url: str = MCP_URL) -> dict:
    request = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "User-Agent": _USER_AGENT,
        },
    )
    with urllib.request.urlopen(request, timeout=20) as response:
        return json.loads(response.read().decode("utf-8"))


class VkusVillClient:
    def __init__(self, transport: Transport = http_transport):
        self._transport = transport

    def search(self, q: str, limit: int) -> list[dict]:
        data = self._call("vkusvill_products_search", {"q": q, "limit": limit, "mode": "full"})
        return data["items"]

    def product_details(self, product_id: int) -> dict:
        return self._call("vkusvill_product_details", {"id": product_id})

    def cart_link(self, xml_ids: list[int]) -> str:
        if not xml_ids:
            raise ValueError("корзина пуста: передай хотя бы один xml_id товара")
        products = [{"xml_id": xml_id, "q": 1} for xml_id in xml_ids]
        return self._call("vkusvill_cart_link_create", {"products": products})["link"]

    def _call(self, tool: str, arguments: dict):
        response = self._transport(
            {
                "jsonrpc": "2.0",
                "id": 1,
                "method": "tools/call",
                "params": {"name": tool, "arguments": arguments},
            }
        )
        if "error" in response:
            raise ValueError(f"ВкусВилл отклонил запрос {tool}: {response['error']['message']}")
        result = response["result"]
        text = "".join(part["text"] for part in result["content"] if part["type"] == "text")
        if result.get("isError"):
            raise ValueError(f"ВкусВилл вернул ошибку {tool}: {text}")
        body = json.loads(text)
        if not body["ok"]:
            raise ValueError(f"ВкусВилл вернул ошибку {tool}: {body['error']['message']}")
        return body["data"]
